filled as (
  update public.major_events e
  set top8 = v.top8, saved_at = now()
  from v
  where e.major_slug = v.major_slug and e.event_id = v.event_id and jsonb_array_length(e.top8) <= 2
  returning e.major_slug
)
update public.majors m
set source_url = v.page
from v
where m.slug = v.major_slug and m.source = 'manual' and m.source_url like 'https://liquipedia.net/smash/Major_Tournaments/%';
